\echo ''
\echo '=== AFTER: Den Haag rows (expect centrum 7.43 + kust 41.26) ==='
SELECT zone_id, ST_GeometryType(polygon) AS gtype, ST_NumGeometries(polygon) AS parts,
       ROUND((ABS(ST_Area(polygon::geography))/1e6)::numeric,4) AS km2,
       ST_IsValid(polygon) AS valid, effective_from, effective_to
FROM enterprise.nl_compliance_zones WHERE city='Den Haag' ORDER BY effective_from, zone_id;

\echo ''
\echo '=== Sanity: Centrum (Binnenhof in, Scheveningen out) + Kust (Scheveningen in, Binnenhof out) ==='
WITH p AS (
  SELECT 'centrum_Binnenhof_IN' AS loc, 'denhaag_centrum_ze_zone_2025' AS zid, 4.3134 AS lon, 52.0799 AS lat, 'inside' AS exp UNION ALL
  SELECT 'centrum_Spui_IN','denhaag_centrum_ze_zone_2025',4.3175,52.0760,'inside' UNION ALL
  SELECT 'centrum_Scheveningen_OUT','denhaag_centrum_ze_zone_2025',4.2780,52.1085,'outside' UNION ALL
  SELECT 'kust_SchevBad_IN','denhaag_kust_ze_zone_2026',4.2780,52.1085,'inside' UNION ALL
  SELECT 'kust_Kurhaus_IN','denhaag_kust_ze_zone_2026',4.2790,52.1075,'inside' UNION ALL
  SELECT 'kust_Binnenhof_OUT','denhaag_kust_ze_zone_2026',4.3134,52.0799,'outside'
)
SELECT loc, exp,
  CASE WHEN ST_Contains((SELECT polygon FROM enterprise.nl_compliance_zones WHERE zone_id=p.zid), ST_SetSRID(ST_MakePoint(lon,lat),4326))
       THEN 'inside' ELSE 'outside' END AS act,
  CASE WHEN exp = CASE WHEN ST_Contains((SELECT polygon FROM enterprise.nl_compliance_zones WHERE zone_id=p.zid), ST_SetSRID(ST_MakePoint(lon,lat),4326)) THEN 'inside' ELSE 'outside' END
       THEN 'PASS' ELSE 'FAIL' END AS result
FROM p ORDER BY zid, loc;

INSERT INTO public.pgmigrations (name, run_on)
SELECT '1781300000000_recon-denhaag-split', NOW()
WHERE NOT EXISTS (SELECT 1 FROM public.pgmigrations WHERE name='1781300000000_recon-denhaag-split');

COMMIT;
\echo ''
\echo '=== Den Haag reconciliation COMMITTED ==='
